     3→
     4→using System;
     5→using Nethermind.Core;
     6→using Nethermind.Core.Crypto;
     7→using Nethermind.Core.Extensions;
     8→
     9→namespace Nethermind.Serialization.Rlp.TxDecoders;
    10→
    11→public abstract class BaseTxDecoder<T>(TxType txType, Func<T>? transactionFactory = null)
    12→    : ITxDecoder where T : Transaction, new()
    13→{
    14→    private const int MaxDelayedHashTxnSize = 32768;
    15→    private readonly Func<T> _createTransaction = transactionFactory ?? (static () => new T());
    16→
    17→    public TxType Type => txType;
    18→
    19→    public virtual Transaction? Decode(Span<byte> transactionSequence, RlpStream rlpStream, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
    20→    {
    21→        T transaction = _createTransaction();
    22→        transaction.Type = txType;
    23→
    24→        int transactionLength = rlpStream.ReadSequenceLength();
    25→        int lastCheck = rlpStream.Position + transactionLength;
    26→
    27→        DecodePayload(transaction, rlpStream, rlpBehaviors);
    28→
    29→        if (rlpStream.Position < lastCheck)
    30→        {
    31→            transaction.Signature = DecodeSignature(transaction, rlpStream, rlpBehaviors);
    32→        }
    33→
    34→        if ((rlpBehaviors & RlpBehaviors.AllowExtraBytes) == 0)
    35→        {
    36→            rlpStream.Check(lastCheck);
    37→        }
    38→
    39→        if ((rlpBehaviors & RlpBehaviors.ExcludeHashes) == 0)
    40→        {
    41→            CalculateHash(transaction, transactionSequence);
    42→        }
    43→
    44→        return transaction;
    45→    }
    46→
    47→    protected void CalculateHash(Transaction transaction, ReadOnlySpan<byte> transactionSequence)
    48→    {
    49→        if (transactionSequence.Length <= MaxDelayedHashTxnSize)
    50→        {
    51→            // Delay hash generation, as may be filtered as having too low gas etc
    52→            transaction.SetPreHashNoLock(transactionSequence);
    53→        }
    54→        else
    55→        {
    56→            // Just calculate the Hash as txn too large
    57→            transaction.Hash = Keccak.Compute(transactionSequence);
    58→        }
    59→    }
    60→
    61→    public virtual void Decode(ref Transaction? transaction, int txSequenceStart, ReadOnlySpan<byte> transactionSequence, ref Rlp.ValueDecoderContext decoderContext, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
    62→    {
    63→        transaction ??= _createTransaction();
    64→        transaction.Type = txType;
    65→
    66→        int transactionLength = decoderContext.ReadSequenceLength();
    67→        int lastCheck = decoderContext.Position + transactionLength;
    68→
    69→        DecodePayload(transaction, ref decoderContext, rlpBehaviors);
    70→
    71→        if (decoderContext.Position < lastCheck)
    72→        {
    73→            transaction.Signature = DecodeSignature(transaction, ref decoderContext, rlpBehaviors);
    74→        }
    75→
    76→        if ((rlpBehaviors & RlpBehaviors.AllowExtraBytes) == 0)
    77→        {
    78→            decoderContext.Check(lastCheck);
    79→        }
    80→
    81→        if ((rlpBehaviors & RlpBehaviors.ExcludeHashes) == 0)
    82→        {
    83→            CalculateHash(transaction, txSequenceStart, transactionSequence, ref decoderContext);
    84→        }
    85→    }
    86→
    87→    protected void CalculateHash(Transaction transaction, int txSequenceStart, ReadOnlySpan<byte> transactionSequence, ref Rlp.ValueDecoderContext decoderContext)
    88→    {
    89→        if (transactionSequence.Length <= MaxDelayedHashTxnSize)
    90→        {
    91→            // Delay hash generation, as may be filtered as having too low gas etc
    92→            if (decoderContext.ShouldSliceMemory)
    93→            {
    94→                // Do not copy the memory in this case.
    95→                int currentPosition = decoderContext.Position;
    96→                decoderContext.Position = txSequenceStart;
    97→                transaction.SetPreHashMemoryNoLock(decoderContext.ReadMemory(transactionSequence.Length));
    98→                decoderContext.Position = currentPosition;
    99→            }
   100→            else
   101→            {
   102→                transaction.SetPreHashNoLock(transactionSequence);
   103→            }
   104→        }
   105→        else
   106→        {
   107→            // Just calculate the Hash immediately as txn too large
   108→            transaction.Hash = Keccak.Compute(transactionSequence);
   109→        }
   110→    }
   111→
   112→    public virtual void Encode(Transaction transaction, RlpStream stream, RlpBehaviors rlpBehaviors = RlpBehaviors.None, bool forSigning = false, bool isEip155Enabled = false, ulong chainId = 0)
   113→    {
   114→        int contentLength = GetContentLength(transaction, rlpBehaviors, forSigning, isEip155Enabled, chainId);
   115→
   116→        stream.StartSequence(contentLength);
   117→        EncodePayload(transaction, stream);
   118→        EncodeSignature(transaction.Signature, stream, forSigning, isEip155Enabled, chainId);
   119→    }
   120→
   121→    public virtual int GetLength(Transaction transaction, RlpBehaviors rlpBehaviors, bool forSigning = false, bool isEip155Enabled = false, ulong chainId = 0)
   122→    {
   123→        int txContentLength = GetContentLength(transaction, rlpBehaviors, forSigning, isEip155Enabled, chainId);
   124→        int txPayloadLength = Rlp.LengthOfSequence(txContentLength);
   125→        return txPayloadLength;
   126→    }
   127→
   128→    protected virtual void DecodePayload(Transaction transaction, RlpStream rlpStream, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
   129→    {
   130→        transaction.Nonce = rlpStream.DecodeUInt256();
   131→        DecodeGasPrice(transaction, rlpStream);
   132→        transaction.GasLimit = rlpStream.DecodeLong();
   133→        transaction.To = rlpStream.DecodeAddress();
   134→        transaction.Value = rlpStream.DecodeUInt256();
   135→        transaction.Data = rlpStream.DecodeByteArray();
   136→    }
   137→
   138→    protected virtual void DecodeGasPrice(Transaction transaction, RlpStream rlpStream)
   139→    {
   140→        transaction.GasPrice = rlpStream.DecodeUInt256();
   141→    }
   142→
   143→    protected virtual void DecodePayload(Transaction transaction, ref Rlp.ValueDecoderContext decoderContext, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
   144→    {
   145→        transaction.Nonce = decoderContext.DecodeUInt256();
   146→        DecodeGasPrice(transaction, ref decoderContext);
