    51→        public UInt256 DecodedMaxFeePerGas { get; set; }
    52→        public UInt256 MaxFeePerGas => Supports1559 ? DecodedMaxFeePerGas : GasPrice;
    53→        public bool SupportsAccessList => Type.SupportsAccessList();
