    85→        internal Hash256 CalculateHashInternal()
    86→        {
    87→            Hash256? hash = _hash;
    88→            if (hash is not null) return hash;
    89→
    90→            lock (this)
    91→            {
    92→                hash = _hash;
    93→                if (hash is not null) return hash;
    94→
    95→                if (_preHash.Length > 0)
    96→                {
